INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('vi-t2','official-vi-travel-public','dialogue','Bạn muốn đặt phòng khách sạn. Chọn câu phù hợp.','["Tôi muốn đặt phòng.","Bạn có thể nhắc lại giúp mình không?","Ga gần nhất ở đâu?","Vui lòng xác nhận số phòng học."]','["Tôi muốn đặt phòng."]','[]','','','','','','','',0,1,'','',2,'["hotel","dialogue"]',1,'2026-09-11','2026-09-11');
