INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('tr-professional-x09','official-tr-professional','fill_blank','Hoàn thành ý phù hợp trong ngữ cảnh Workplace & Daily Life: “Thông báo về lịch hoặc nhiệm vụ” tương ứng với ___.','["Thông báo về lịch hoặc nhiệm vụ","Một câu chuyện cổ tích","Mô tả thời tiết","Quảng cáo trò chơi"]','["Thông báo về lịch hoặc nhiệm vụ"]','[]','Trong bộ bài Türkçe, “Thông báo về lịch hoặc nhiệm vụ” được dùng với nghĩa/ý phù hợp là “Thông báo về lịch hoặc nhiệm vụ”.','Dựa vào ngữ cảnh của cụm từ.','','','','','',0,1,'','',2,'["reinforcement","fill-blank","workplace-&-daily-life"]',8,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('tr-professional-x10','official-tr-professional','multiple_select','Chọn HAI hành động phù hợp khi giao tiếp trong bối cảnh Workplace & Daily Life.','["Xác nhận lại thông tin quan trọng","Phản hồi rõ ràng và lịch sự","Bỏ qua yêu cầu mà không trả lời","Đoán thông tin còn thiếu rồi làm ngay"]','["Xác nhận lại thông tin quan trọng","Phản hồi rõ ràng và lịch sự"]','[]','Giao tiếp hiệu quả cần xác nhận thông tin và phản hồi rõ ràng.','','','','','','',0,1,'','',3,'["scenario","multiple-select","communication"]',9,'2026-09-11','2026-09-11');
