INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('ko-school-scenario-x24','official-ko-school-scenario','multiple_choice','Khi áp dụng nội dung của “한국어 — School & Classroom Scenarios” vào thực tế, mục tiêu quan trọng nhất là gì?','["Hiểu ý, dùng đúng ngữ cảnh và phản hồi phù hợp","Chỉ ghi nhớ đáp án của một lần chơi","Trả lời càng nhanh càng tốt dù chưa hiểu","Bỏ qua phần giải thích"]','["Hiểu ý, dùng đúng ngữ cảnh và phản hồi phù hợp"]','[]','Sky First Games ưu tiên khả năng sử dụng ngôn ngữ trong tình huống thực tế, không chỉ ghi nhớ đáp án.','','','','','','',0,1,'','',4,'["mastery","real-life","reflection"]',23,'2026-09-11','2026-09-11');
